(function(){var d=document;function page(n){return n.closest('.qb-page')||d.documentElement}function fit(n){var p=n.querySelector(':scope>.qb-nav__panel'),b=n.getAttribute('data-qb-collapse');if(!p||!b)return;var w=page(n).clientWidth<=(b==='tablet'?767:480);if(w!==n._qbNarrow){n._qbNarrow=w;p.open=!w}}function init(n){if(n._qb)return;n._qb=1;fit(n);if(window.ResizeObserver)new ResizeObserver(function(){fit(n)}).observe(page(n));n.addEventListener('toggle',function(e){var t=e.target;if(!t.open)return;if(t.classList.contains('qb-nav__sub')){n.querySelectorAll('details.qb-nav__sub[open]').forEach(function(o){if(o!==t&&o.getAttribute('name')===t.getAttribute('name'))o.open=false})}else if(t.classList.contains('qb-nav__panel')&&n.classList.contains('qb-nav--horizontal')){n.querySelectorAll('[data-qb-current-path]>details.qb-nav__sub').forEach(function(o){o.open=true})}},true);n.addEventListener('keydown',function(e){if(e.key!=='Escape')return;var t=e.target.closest('details[open]');if(!t||!n.contains(t))return;t.open=false;t.querySelector(':scope>summary').focus();e.stopPropagation()})}function all(){d.querySelectorAll('nav.qb-nav').forEach(init)}all();if(d.readyState==='loading')d.addEventListener('DOMContentLoaded',all);d.addEventListener('click',function(e){d.querySelectorAll('nav.qb-nav--horizontal details.qb-nav__sub[open]').forEach(function(o){if(!o.contains(e.target))o.open=false})})})();
